from __future__ import annotations

from pathlib import Path
import re


def replace_once(path: Path, old: str, new: str, label: str) -> None:
    text = path.read_text()
    if old not in text:
        raise SystemExit(f"{label} block not found in {path}")
    path.write_text(text.replace(old, new, 1))


health = Path("src/autotrade/research/health.py")
replace_once(
    health,
    '''                CREATE TABLE IF NOT EXISTS health_transitions_v2 (\n                    transition_fingerprint TEXT PRIMARY KEY,\n''',
    '''                CREATE TABLE IF NOT EXISTS health_recovery_acks_v2 (\n                    entity_kind TEXT NOT NULL,\n                    entity_id TEXT NOT NULL,\n                    recovery_id TEXT NOT NULL,\n                    request_fingerprint TEXT NOT NULL,\n                    confirmed_by TEXT NOT NULL,\n                    applied_at TEXT NOT NULL,\n                    PRIMARY KEY(entity_kind, entity_id, recovery_id)\n                );\n                CREATE TABLE IF NOT EXISTS health_transitions_v2 (\n                    transition_fingerprint TEXT PRIMARY KEY,\n''',
    "health recovery ack schema",
)

start = health.read_text().index("    def acknowledge_recovery(\n")
end = health.read_text().index("    def _assert_binding(\n", start)
text = health.read_text()
new_method = '''    def acknowledge_recovery(\n        self,\n        baseline: HealthBaseline,\n        observed: HealthObservationSeries,\n        policy: HealthPolicy,\n        *,\n        recovery_id: str,\n        confirmed_by: str,\n        now: datetime,\n    ) -> HealthControlState:\n        _identity(recovery_id, "recovery_id")\n        _identity(confirmed_by, "confirmed_by")\n        if not _aware(now):\n            raise ValueError("recovery time must be timezone-aware")\n        if baseline.entity_id != observed.entity_id or baseline.entity_kind is not observed.entity_kind:\n            raise HealthRecoveryRejected("recovery observation entity does not match baseline")\n        request_fingerprint = _hash(\n            {\n                "recovery_id": recovery_id,\n                "entity_id": baseline.entity_id,\n                "entity_kind": baseline.entity_kind.value,\n                "baseline_fingerprint": baseline.fingerprint,\n                "observation_series_fingerprint": observed.fingerprint,\n                "policy_fingerprint": policy.fingerprint,\n                "confirmed_by": confirmed_by,\n            }\n        )\n\n        conn = self._connect()\n        try:\n            conn.execute("BEGIN IMMEDIATE")\n            row = conn.execute(\n                "SELECT * FROM health_state_v2 WHERE entity_kind=? AND entity_id=?",\n                (baseline.entity_kind.value, baseline.entity_id),\n            ).fetchone()\n            if row is None:\n                conn.rollback()\n                raise HealthRecoveryRejected("no health state exists for entity")\n            current = _state_from_row(row)\n            self._assert_binding(\n                current,\n                baseline_fingerprint=baseline.fingerprint,\n                policy_fingerprint=policy.fingerprint,\n            )\n\n            ack = conn.execute(\n                """\n                SELECT request_fingerprint FROM health_recovery_acks_v2\n                WHERE entity_kind=? AND entity_id=? AND recovery_id=?\n                """,\n                (baseline.entity_kind.value, baseline.entity_id, recovery_id),\n            ).fetchone()\n            if ack is not None:\n                if ack["request_fingerprint"] != request_fingerprint:\n                    raise HealthStateConflict("recovery_id reused with conflicting request")\n                conn.commit()\n                return current\n\n            assessment = assess_health(baseline, observed, policy, now=now)\n            if assessment.proposed_state is not HealthState.HEALTHY:\n                raise HealthRecoveryRejected("recovery requires fresh HEALTHY evidence")\n            if current.state is HealthState.RETIRED:\n                raise HealthRecoveryRejected("RETIRED state cannot be recovered automatically")\n\n            if current.state is HealthState.HEALTHY:\n                conn.execute(\n                    """\n                    INSERT INTO health_recovery_acks_v2(\n                        entity_kind,entity_id,recovery_id,request_fingerprint,confirmed_by,applied_at\n                    ) VALUES(?,?,?,?,?,?)\n                    """,\n                    (\n                        current.entity_kind.value,\n                        current.entity_id,\n                        recovery_id,\n                        request_fingerprint,\n                        confirmed_by,\n                        now.isoformat(),\n                    ),\n                )\n                conn.commit()\n                return current\n\n            target = (\n                HealthState.HEALTHY\n                if current.state is HealthState.DEGRADED\n                else HealthState.DEGRADED\n            )\n            updated = HealthControlState(\n                entity_id=current.entity_id,\n                entity_kind=current.entity_kind,\n                state=target,\n                version=current.version + 1,\n                distinct_quarantine_count=current.distinct_quarantine_count,\n                baseline_fingerprint=current.baseline_fingerprint,\n                policy_fingerprint=current.policy_fingerprint,\n                last_assessment_fingerprint=assessment.fingerprint,\n                updated_at=now,\n            )\n            self._upsert_state(conn, updated)\n            conn.execute(\n                """\n                INSERT INTO health_recovery_acks_v2(\n                    entity_kind,entity_id,recovery_id,request_fingerprint,confirmed_by,applied_at\n                ) VALUES(?,?,?,?,?,?)\n                """,\n                (\n                    current.entity_kind.value,\n                    current.entity_id,\n                    recovery_id,\n                    request_fingerprint,\n                    confirmed_by,\n                    now.isoformat(),\n                ),\n            )\n            self._append_transition(\n                conn,\n                entity_kind=current.entity_kind,\n                entity_id=current.entity_id,\n                from_state=current.state,\n                to_state=target,\n                baseline_fingerprint=current.baseline_fingerprint,\n                policy_fingerprint=current.policy_fingerprint,\n                assessment_fingerprint=assessment.fingerprint,\n                action="ACKNOWLEDGED_RECOVERY",\n                confirmed_by=confirmed_by,\n                now=now,\n            )\n            conn.commit()\n            return updated\n        except Exception:\n            if conn.in_transaction:\n                conn.rollback()\n            raise\n        finally:\n            conn.close()\n\n'''
health.write_text(text[:start] + new_method + text[end:])

bridge = Path("src/autotrade/health_bridge.py")
replace_once(
    bridge,
    '''                CREATE TABLE IF NOT EXISTS health_bridge_transitions (\n                    transition_id TEXT PRIMARY KEY,\n''',
    '''                CREATE TABLE IF NOT EXISTS health_bridge_recovery_acks (\n                    entity_kind TEXT NOT NULL,\n                    entity_id TEXT NOT NULL,\n                    recovery_id TEXT NOT NULL,\n                    request_fingerprint TEXT NOT NULL,\n                    health_state_fingerprint TEXT NOT NULL,\n                    confirmed_by TEXT NOT NULL,\n                    applied_at TEXT NOT NULL,\n                    PRIMARY KEY(entity_kind, entity_id, recovery_id)\n                );\n                CREATE TABLE IF NOT EXISTS health_bridge_transitions (\n                    transition_id TEXT PRIMARY KEY,\n''',
    "bridge recovery ack schema",
)

text = bridge.read_text()
start = text.index("    def acknowledge_recovery(\n")
end = text.index("    def effective_control(\n", start)
new_bridge_method = '''    def acknowledge_recovery(\n        self,\n        *,\n        entity_id: str,\n        entity_kind: HealthEntityKind,\n        recovery_id: str,\n        confirmed_by: str,\n        now: datetime,\n    ) -> HealthBridgeState:\n        _identity(recovery_id, "recovery_id")\n        _identity(confirmed_by, "confirmed_by")\n        _validate_time(now)\n        health = self._authoritative_health(entity_id, entity_kind)\n        desired_mode, _ = self._mapped_control(health.state)\n        request_fingerprint = _hash(\n            {\n                "recovery_id": recovery_id,\n                "entity_id": entity_id,\n                "entity_kind": entity_kind.value,\n                "health_state_fingerprint": health.fingerprint,\n                "confirmed_by": confirmed_by,\n            }\n        )\n\n        conn = self._runtime.connect()\n        try:\n            conn.execute("BEGIN IMMEDIATE")\n            current = self._current_tx(conn, entity_id, entity_kind)\n            if current is None:\n                raise HealthBridgeRecoveryRejected("no bridge state exists for entity")\n            self._assert_binding(current, health)\n\n            ack = conn.execute(\n                """\n                SELECT request_fingerprint FROM health_bridge_recovery_acks\n                WHERE entity_kind=? AND entity_id=? AND recovery_id=?\n                """,\n                (entity_kind.value, entity_id, recovery_id),\n            ).fetchone()\n            if ack is not None:\n                if ack["request_fingerprint"] != request_fingerprint:\n                    raise HealthBridgeConflict("recovery_id reused with conflicting request")\n                conn.execute("COMMIT")\n                return current\n\n            self._require_fresh_health(health, now=now)\n            if health.version < current.health_state_version:\n                raise HealthBridgeRecoveryRejected("recovery health state is older than bridge evidence")\n            if (\n                health.version == current.health_state_version\n                and health.fingerprint != current.health_state_fingerprint\n            ):\n                raise HealthBridgeConflict("health state version identity conflict")\n            if _SEVERITY[desired_mode] >= _SEVERITY[current.mode]:\n                raise HealthBridgeRecoveryRejected(\n                    "recovery requires authoritative health evidence supporting a less restrictive mode"\n                )\n\n            target_severity = max(_SEVERITY[desired_mode], _SEVERITY[current.mode] - 1)\n            target_mode = _MODE_BY_SEVERITY[target_severity]\n            target_multiplier = self._multiplier_for_mode(target_mode, None)\n            updated = HealthBridgeState(\n                entity_id=current.entity_id,\n                entity_kind=current.entity_kind,\n                mode=target_mode,\n                risk_multiplier=target_multiplier,\n                health_state_version=health.version,\n                health_state_fingerprint=health.fingerprint,\n                baseline_fingerprint=current.baseline_fingerprint,\n                policy_fingerprint=current.policy_fingerprint,\n                bridge_version=current.bridge_version + 1,\n                updated_at=now,\n            )\n            self._upsert_state_tx(conn, updated)\n            conn.execute(\n                """\n                INSERT OR IGNORE INTO health_bridge_applied(\n                    entity_kind,entity_id,health_state_fingerprint,applied_at\n                ) VALUES(?,?,?,?)\n                """,\n                (entity_kind.value, entity_id, health.fingerprint, now.isoformat()),\n            )\n            conn.execute(\n                """\n                INSERT INTO health_bridge_recovery_acks(\n                    entity_kind,entity_id,recovery_id,request_fingerprint,\n                    health_state_fingerprint,confirmed_by,applied_at\n                ) VALUES(?,?,?,?,?,?,?)\n                """,\n                (\n                    entity_kind.value,\n                    entity_id,\n                    recovery_id,\n                    request_fingerprint,\n                    health.fingerprint,\n                    confirmed_by,\n                    now.isoformat(),\n                ),\n            )\n            self._append_transition_tx(\n                conn,\n                state=updated,\n                from_mode=current.mode,\n                action="ACKNOWLEDGED_RECOVERY",\n                confirmed_by=confirmed_by,\n                now=now,\n            )\n            safety_version = self._bump_safety_version_tx(conn, now=now)\n            _append_ledger_tx(\n                conn,\n                event_id=(\n                    f"health-bridge-recovery:{entity_kind.value}:{entity_id}:"\n                    f"{recovery_id}"\n                ),\n                event_type="HEALTH_BRIDGE_RECOVERY_ACKNOWLEDGED",\n                occurred_at=now,\n                payload={\n                    "entity_kind": entity_kind.value,\n                    "entity_id": entity_id,\n                    "recovery_id": recovery_id,\n                    "from_mode": current.mode.value,\n                    "to_mode": updated.mode.value,\n                    "confirmed_by": confirmed_by,\n                    "health_state_version": str(health.version),\n                    "health_state_fingerprint": health.fingerprint,\n                    "bridge_version": str(updated.bridge_version),\n                    "safety_state_version": str(safety_version),\n                },\n            )\n            conn.execute("COMMIT")\n            return updated\n        except Exception:\n            if conn.in_transaction:\n                conn.execute("ROLLBACK")\n            raise\n        finally:\n            conn.close()\n\n'''
bridge.write_text(text[:start] + new_bridge_method + text[end:])

# Existing tests must opt in to an explicit recovery request identity. Give each
# existing acknowledgement a unique ID; dedicated retry tests below exercise
# deliberate reuse of the same ID.
for test_name in (
    "tests/test_r4_health_drift.py",
    "tests/test_r4_health_binding_integrity.py",
    "tests/test_r4_health_bridge.py",
):
    path = Path(test_name)
    text = path.read_text()
    counter = 0
    pattern = re.compile(r"(?m)^(\s*)confirmed_by=(.+)$")

    def repl(match: re.Match[str]) -> str:
        nonlocal_counter[0] += 1
        indent = match.group(1)
        return (
            f'{indent}recovery_id="{path.stem}-recovery-{nonlocal_counter[0]}",\n'
            f"{indent}confirmed_by={match.group(2)}"
        )

    nonlocal_counter = [0]
    text = pattern.sub(repl, text)
    path.write_text(text)
